INSERT INTO casbin_rule (ptype, v0, v1, v2) SELECT 'p', 'MERCHANT_ADMIN', '/v1/permissions', 'GET' WHERE NOT EXISTS (SELECT 1 FROM casbin_rule WHERE ptype='p' AND v0='MERCHANT_ADMIN' AND v1='/v1/permissions' AND v2='GET');
